import{_ as r,o,c as t,a5 as a}from"./chunks/framework.DJo0M80U.js";const f=JSON.parse('{"title":"第五步：什么情况下，浏览器会受哪个头影响","description":"场景 1：普通首次访问 浏览器没有本地缓存条目，就发普通请求。返回后，是否存、存多久，由响应头里的 Cache Control / Expires / 状态码可缓存性决定。若以后要做重验证，还要看这次响应有没有 ETag / Last Modified。(RFC Editor)。","frontmatter":{"title":"第五步：什么情况下，浏览器会受哪个头影响","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","前端知识复习"],"description":"场景 1：普通首次访问 浏览器没有本地缓存条目，就发普通请求。返回后，是否存、存多久，由响应头里的 Cache Control / Expires / 状态码可缓存性决定。若以后要做重验证，还要看这次响应有没有 ETag / Last Modified。(RFC Editor)。","sidebarWeight":35,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/考点难点/浏览器的缓存机制/第五步：什么情况下，浏览器会受哪个头影响.md"},"headers":[],"relativePath":"posts/前端面试与实战/01-前端知识复习/浏览器的缓存机制/第五步：什么情况下，浏览器会受哪个头影响.md","filePath":"posts/前端面试与实战/01-前端知识复习/浏览器的缓存机制/第五步：什么情况下，浏览器会受哪个头影响.md"}'),s={name:"posts/前端面试与实战/01-前端知识复习/浏览器的缓存机制/第五步：什么情况下，浏览器会受哪个头影响.md"};function n(c,e,l,d,i,g){return o(),t("div",null,[...e[0]||(e[0]=[a('<div><h1 id="第五步-什么情况下-浏览器会受哪个头影响" tabindex="-1">第五步：什么情况下，浏览器会受哪个头影响 <a class="header-anchor" href="#第五步-什么情况下-浏览器会受哪个头影响" aria-label="Permalink to &quot;第五步：什么情况下，浏览器会受哪个头影响&quot;">​</a></h1><blockquote><p>本节目标：理解“第五步：什么情况下，浏览器会受哪个头影响”的核心思路，并能把它用于实际开发或面试表达。 <strong>场景 1：普通首次访问</strong> 浏览器没有本地缓存条目，就发普通请求。返回后，是否存、存多久，由响应头里的 Cache-Control / Expires / 状态码可缓存性决定。若以后要做重验证，还要看这次响应有没有 ETag / Last-Modified。(<a href="https://www.rfc-editor.org/rfc/rfc9111.html" target="_blank" rel="noreferrer">RFC Editor</a>) <strong>场景 2：普通再次访问，且缓存仍 fresh</strong> 浏览器直接复用本地缓存，不需要发 If-None-Match / If-Modified-Since。fresh 的判断主要看 Cache-Control: max-age、Expires、Age。(<a href="https://www.rfc-editor.org/rfc/rfc9111.html" target="_blank" rel="noreferrer">RFC Editor</a>) <strong>场景 3：缓存 stale，但响应带 ETag</strong> 浏览器通常会带 If-None-Match 去重验证。服务端返回 304，浏览器继续用本地实体；返回 200，则替换成本次响应。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching" target="_blank" rel="noreferrer">MDN Web Docs</a>) <strong>场景 4：缓存 stale，没有 ETag，但带 Last-Modified</strong> 浏览器通常会带 If-Modified-Since。服务端若认为未修改，回 304；否则回新内容。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Last-Modified?utm_source=chatgpt.com" target="_blank" rel="noreferrer">MDN Web Docs</a>) <strong>场景 5：响应是 no-cache</strong> 即使缓存没过期，也不能直接复用；每次都要重验证。这里最容易看到“本地有缓存，但仍然每次都发请求”的现象。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>) <strong>场景 6：响应是 no-store</strong> 浏览器不该留下缓存条目；下一次访问通常只能重新请求。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>) <strong>场景 7：资源带 hash，且 max-age 很长，外加 immutable</strong> 浏览器在 fresh 窗口内可以非常激进地复用，不必在刷新时多做没必要的条件请求。这是现代静态资源最推荐的姿势。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching" target="_blank" rel="noreferrer">MDN Web Docs</a>) <strong>场景 8：用户普通刷新页面</strong> 浏览器通常会带 Cache-Control: max-age=0；也可能结合验证器发条件请求。它不是“清空所有缓存”，而是更偏向“重新确认是否最新”。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>) <strong>场景 9：用户强制刷新</strong> 浏览器通常会带 Cache-Control: no-cache，要求先验证再复用；实际资源是否重新下载，还要看服务端是否回 304 还是 200。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>) <strong>场景 10：fetch(url, { cache: ... })</strong> 这时优先看 Request.cache 模式，而不是只看服务端响应头。也就是说，你的 JS 代码可以把浏览器的默认缓存决策改掉。(<a href="https://developer.mozilla.org/en-US/docs/Web/API/Request/cache" target="_blank" rel="noreferrer">MDN Web Docs</a>) <strong>场景 11：Service Worker 已接管</strong> 这时真正的“先查什么、再查什么”由 Service Worker 决定。它可能先用 Cache API，也可能完全不理 HTTP cache。(<a href="https://developer.mozilla.org/en-US/docs/Web/API/Service_Worker_API/Using_Service_Workers" target="_blank" rel="noreferrer">MDN Web Docs</a>) <strong>场景 12：用户点浏览器后退/前进</strong> 如果页面满足条件，浏览器优先可能直接从 bfcache 恢复整页。这个场景下，你看到的是“页面瞬间回来”，不是一次普通的 HTTP cache 命中。(<a href="https://developer.mozilla.org/en-US/docs/Glossary/bfcache" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p></blockquote></div>',1)])])}const _=r(s,[["render",n]]);export{f as __pageData,_ as default};
